using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using Verse;using Verse.AI;using RimWorld;using UnityEngine;using PlayableRecreation;using PlayableRecreation.UI;using Chess;using Chess.Core;using PRQA;
public static class Command{
public static string Run(){Host.Watch=null;foreach(var x in Find.WindowStack.Windows.ToList())if(x is Dialog_ModSettings||x is Dialog_MiniGame||x is FloatMenu)x.Close();TogetherMatch.Reset();TogetherInvite.Reset();var pair=(Pawn[])Host.State["punchPair"];var p=pair[0];var o=pair[1];var b=(Thing)Host.State["chess"];var g=b.TryGetComp<CompMiniGame>().Game;var f=BindingFlags.Instance|BindingFlags.NonPublic;var log=Host.Root+"/final-runtime.txt";File.WriteAllText(log,"Actual jobs, normal ticks, UI action callbacks.\n");Action<string> note=s=>File.AppendAllText(log,s+"\n");PRMod.Settings.immersionMode=true;PRMod.Settings.playTogether=true;PRMod.Settings.playTogetherVisitors=true;PRMod.Settings.playTogetherInvites=false;note("invites OFF: "+TogetherInvite.ForceInvite());PRMod.Settings.playTogetherInvites=true;PRMod.Settings.playTogetherInviteScale=0;note("frequency 0: "+TogetherInvite.ForceInvite());PRMod.Settings.playTogetherInviteScale=100;foreach(var id in new[]{"PR_Stargazing","PR_Slots"}){var def=DefDatabase<MiniGameDef>.GetNamed(id);note(id+" hasMatch="+def.hasMatch+" together="+Together.AppliesTo(def));}
foreach(var q in pair){q.jobs.EndCurrentJob(JobCondition.InterruptForced);q.drafter.Drafted=false;q.needs.food.CurLevelPercentage=1;q.needs.rest.CurLevelPercentage=1;q.needs.joy.CurLevelPercentage=.3f;}p.Position=b.Position+new IntVec3(-6,0,-6);o.Position=b.Position+new IntVec3(6,0,-6);p.Notify_Teleported();o.Notify_Teleported();var old=GameComponent_Recreation.Current.SessionFor(b);if(old!=null)GameComponent_Recreation.Current.Remove(old);GameEntry.Commit(g,b,p,o,2,true);foreach(var q in pair)q.jobs.EndCurrentJob(JobCondition.InterruptForced);int stage=0,start=Find.TickManager.TicksGame;Dialog_MiniGame d=null;Host.Watch=()=>{int elapsed=Find.TickManager.TicksGame-start;
if(stage==0&&elapsed>80){note("cancelled both, "+elapsed+" ticks: judge="+Together.Judge(p,o,b,g)+","+Together.Judge(o,p,b,g)+"\n"+TogetherMatch.Describe());GameEntry.Commit(g,b,p,o,2,true);stage=1;start=Find.TickManager.TicksGame;}
else if(stage==1){d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(d==null){if(elapsed>1800){note("practice arrival timeout");Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}return;}note("practice open jobs="+p.CurJobDef+","+o.CurJobDef);p.interactions.TryInteractWith(o,InteractionDefOf.Chitchat);o.interactions.TryInteractWith(p,InteractionDefOf.Insult);stage=2;start=Find.TickManager.TicksGame;Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;}
else if(stage==2&&elapsed>700){var talk=(List<string>)typeof(Dialog_MiniGame).GetField("talk",f).GetValue(d);note("forced vanilla Chitchat+Insult, after "+elapsed+" normal ticks talk="+string.Join(" | ",talk));Host.State["talkWindow"]=d;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;Host.State["finalPair"]=pair;}
};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Started final cancellation and talk pipeline checks.";}}
